b=Path(__file__).resolve().parent;src=b/'raw-phase-projectiles/12-codebreak-sproto3106-p1-projectiles-text.png';a=np.array(Image.open(src).convert('RGBA'))[:1536];yy,xx=np.indices(a.shape[:2]);edge=(xx%512<12)|(xx%512>=500)|(yy%512<12)|(yy%512>=500);r,g,bb=a[:,:,0].astype(int),a[:,:,1].astype(int),a[:,:,2].astype(int);safe=(np.maximum(np.maximum(r,g),bb)<=50)|((abs(r-bb)<=70)&(g<=80)&(np.minimum(r,bb)-g>=15));assert not (edge&~safe).any();a[edge]=[255,0,255,255];out=Image.new('RGBA',(2048,2048),(255,0,255,255));out.paste(Image.fromarray(a),(0,0));out.paste(Image.fromarray(a[:512]),(0,1536));out.save(b/'raw-phase-projectiles/12p1-ABC-only-validation-temporary.png');Image.fromarray(edge.astype('uint8')*255).save(b/'12p1-ABC-reviewed-divider-mask.png');(b/'12p1-ABC-grid-removal.json').write_text(json.dumps({'source':str(src),'sourceSha256':hashlib.sha256(src.read_bytes()).hexdigest(),'reviewedSeparatorOnly':True,'width':12,'allPixelsValidatedBlackMagentaOrDarkFieldFringe':True,'removedPixels':int(edge.sum()),'temporaryDuplicateFourthRowNeverShipped':True},indent=2))
